function art(id) {
  return '<svg class="art" viewBox="0 0 320 200" role="img" aria-label="' + id + ' illustration">' + (ARTS[id] || "") + '</svg>';
}

function esc(t) { return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;"); }
function catCard(c) {
  return '<a class="card" href="#' + c.id + '">' + art(c.id) + '<span class="tag">' + c.tag + '</span><h3>' + esc(c.name) + '</h3><p>' + esc(c.intro) + '</p><span class="more">View category →</span></a>';
}
