(document.getElementById("quote") || document.createElement("form")).addEventListener("submit", function (e) {
  e.preventDefault();
  function v(id) { var el = document.getElementById(id); return el ? el.value.trim() : ""; }
  var name = document.getElementById("f-name"), email = document.getElementById("f-email");
  var status = document.getElementById("f-status");
  if (!name.value.trim() || !email.value.trim() || !email.checkValidity()) {
    status.className = "note";
    status.textContent = "Please add your name and a valid email address.";
    (name.value.trim() ? email : name).focus();
    return;
  }
  var lines = ["Hello Teak & Tide, I would like a quote.", "",
    "Name: " + v("f-name"), v("f-company") ? "Company: " + v("f-company") : "", "Email: " + v("f-email"),
    v("f-country") ? "Country: " + v("f-country") : "", "Product category: " + v("f-cat"),
    v("f-qty") ? "Quantity: " + v("f-qty") : "", "Service: " + v("f-svc"),
    v("f-date") ? "Needed by: " + v("f-date") : "", v("f-price") ? "Target price: " + v("f-price") : "", v("f-msg") ? "Details: " + v("f-msg") : ""];
  try {
    var d = {"form-name":"quote", name:v("f-name"), company:v("f-company"), email:v("f-email"), country:v("f-country"), category:v("f-cat"), qty:v("f-qty"), service:v("f-svc"), date:v("f-date"), price:v("f-price"), msg:v("f-msg")};
    fetch("/", {method:"POST", headers:{"Content-Type":"application/x-www-form-urlencoded"}, body:Object.keys(d).map(function(k){return encodeURIComponent(k)+"="+encodeURIComponent(d[k])}).join("&")}).catch(function(){});
  } catch (err) {}
  var url = waLink(lines.filter(function (l, i) { return l || i === 1; }).join("\n"));
  status.className = "sent";
  status.innerHTML = "";
  status.appendChild(document.createTextNode("Thank you, " + v("f-name") + ". Your enquiry is ready. Tap the button to send it to us on WhatsApp."));
  var a = document.createElement("a");
  a.className = "btn btn-green wa-send"; a.href = url; a.target = "_blank"; a.rel = "noopener";
  a.textContent = "Open WhatsApp and send";
  status.appendChild(document.createElement("br")); status.appendChild(a);
  var w = null; try { w = window.open(url, "_blank", "noopener"); } catch (err) {}
});
